def split_double(flag, other, value):
    return (
        not flag and not
        not
        value
    )

def split_triple(flag, other, value):
    return (
        not flag and not
        not
        not
        value
    )

def split_quadruple(flag, other, value):
    return (
        not flag and not
        not
        not
        not
        value
    )

def return_line_split(flag, other, value):
    return (not flag and not
        not not value
    )
